"""Assemble bounded C04 diagnostics and CAD feature provenance."""
from pathlib import Path
import hashlib,json,time
from datetime import datetime
from zoneinfo import ZoneInfo
import numpy as np
import gmsh
from scipy.optimize import linear_sum_assignment
W=Path(__file__).resolve().parents[1];O=W/'data/copv/c04_diagnostics_v1'
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    target=O/'diagnosis.json'
    if target.exists():raise RuntimeError('Preserve existing diagnosis; choose another version')
    features=[]
    for suffix in ['0000','0011','0002','0018']:
        case='copv_c04_'+suffix;partition=W/'data/copv/c04_pilot_v1/cases'/case/'partition_v2';review=read(partition/'partition_review.json');gmsh.initialize();gmsh.option.setNumber('General.Terminal',0)
        try:
            gmsh.model.occ.importShapes(str(partition/'structural_partition.brep'));occ=gmsh.model.occ;occ.synchronize();vols=gmsh.model.getEntities(3);expected=review['volume_records'];mass=np.array([occ.getMass(3,t) for _,t in vols]);com=np.array([occ.getCenterOfMass(3,t) for _,t in vols]);em=np.array([r['volume_mm3'] for r in expected]);ec=np.array([r['center_mm'] for r in expected]);aa,bb=linear_sum_assignment((1000*np.log(mass[:,None]/em[None,:]))**2+np.sum((com[:,None,:]-ec[None,:,:])**2,axis=-1));pid={vols[int(a)][1]:expected[int(b)]['part_id'] for a,b in zip(aa,bb)};curves=[]
            for _,tag in gmsh.model.getEntities(1):
                faces,_=gmsh.model.getAdjacencies(1,tag);owners={int(v) for f in faces for v in gmsh.model.getAdjacencies(2,int(f))[0]};curves.append(dict(curve=tag,type=gmsh.model.getType(1,tag),length_mm=occ.getMass(1,tag),bbox_mm=list(gmsh.model.getBoundingBox(1,tag)),part_ids=sorted({pid[v] for v in owners if v in pid})))
            features.append(dict(case_id=case,partition_sha256=sha(partition/'structural_partition.brep'),curves_below_mesher_min_05mm=sum(c['length_mm']<.5 for c in curves),shortest_curves=sorted(curves,key=lambda c:c['length_mm'])[:25],nominal_collar_start_added_thickness_mm=.03,nominal_adhesive_thickness_mm=.15,scope='Short-edge lengths diagnose scale mismatch; they are not measurements of minimum wall thickness or proof of invalid CAD.'))
        finally:gmsh.finalize()
